import { v } from "convex/values";
import { api, internal } from "./_generated/api";
import type { Doc, Id } from "./_generated/dataModel";
import { internalAction, internalMutation, internalQuery, type ActionCtx } from "./_generated/server";
import type { ContactLite } from "./emailContacts";
import {
  COVERS_ABOUT,
  COVERS_CONTACT_COLUMNS,
  COVERS_DINER_GROUPS,
  COVERS_DINERS,
  COVERS_INDIVIDUALS,
  COVERS_LIST_MAPPING,
  COVERS_RESTAURANTS,
  COVERS_SENDER,
  COVERS_SITE,
  coversFooter,
  coversItems,
  coversKit,
  type CoversContact,
} from "./emailDemoCovers";
import { andList } from "./emailItems";
import { cite, dropAssets, dropCovers, purge } from "./emailSeed";
import { cachedQlooGet } from "./qloo";
import type { AudienceProfile, EmailKit } from "./emailTypes";

// Seeds Covers, the Email service's second demo brand (data in
// emailDemoCovers.ts), as a demo master: a London restaurant booking app with
// its kit, 48 restaurants matched to Qloo places, two regulars kept as
// individual contacts, and eight diners sorted into two taste groups (six by
// what they booked, two new members by age, gender and how close they live
// to each group's restaurants), read through the same pipeline a merchant's
// CSV goes through. No campaigns: the merchant writes those.
//
//   npx convex run emailSeedCovers:run                                  # local site
//   npx convex run emailSeedCovers:run '{"site":"https://…/covers"}'    # deployed site
//   npx convex run emailSeed:status '{"slug":"covers"}'                 # what exists, and how far it got
//
// `run` replaces any earlier Covers master (and the account copies made from
// it), creates the brand, restaurants and uploads, and starts reading the
// regulars; `step` follows the uploads in scheduled steps (the regulars first,
// then the diners) and calls `finish`, which names the two groups, writes
// their briefs and copies the photos into storage.

const SLUG = "covers";
/** How long `step` keeps waiting for the lists (polls every 15 s). */
const MAX_STEPS = 60;

/* Brand ------------------------------------------------------------------------------ */

export const existing = internalQuery({
  args: {},
  handler: async (ctx) => {
    const master = await ctx.db
      .query("emailBrands")
      .withIndex("by_slug", (q) => q.eq("slug", SLUG))
      .unique();
    if (!master) return null;
    const copies = await ctx.db
      .query("emailBrands")
      .withIndex("by_demo", (q) => q.eq("demo", true).eq("demoOf", master._id))
      .collect();
    return { master, copies: copies.map((c) => c._id) };
  },
});

export const insertBrand = internalMutation({
  args: { site: v.string(), kit: v.any() },
  returns: v.id("emailBrands"),
  handler: async (ctx, { site, kit }) => {
    const now = Date.now();
    return ctx.db.insert("emailBrands", {
      slug: SLUG,
      name: "Covers",
      url: site,
      status: "ready",
      setup: { status: "done", progress: { value: 1, label: "Ready" }, at: now },
      kit,
      about: COVERS_ABOUT,
      footer: coversFooter(site),
      sender: COVERS_SENDER,
      // A master: no owner, no demoOf. emailDemo.provision copies it into each account.
      demo: true,
      createdAt: now,
      updatedAt: now,
    });
  },
});

/** Uploads the logo, its light version and the square mark to Convex storage, so emails load them wherever the site runs. */
async function storeAssets(ctx: ActionCtx, site: string): Promise<EmailKit> {
  const store = async (b64: string) => {
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const id = await ctx.storage.store(new Blob([bytes], { type: "image/png" }));
    return (await ctx.storage.getUrl(id))!;
  };
  const kit = coversKit(site);
  return { ...kit, logo: { ...kit.logo!, src: await store(LOGO_PNG), light: await store(LOGO_LIGHT_PNG) }, icon: await store(MARK_PNG) };
}

/* Qloo tags ------------------------------------------------------------------------------ */

/**
 * The tag types on a Qloo place that say what kind of restaurant it is. A
 * place carries 100 to 200 tags, most of them practical (payments, parking,
 * accessibility); dishes ("duck breast"), ambience ("sophisticated") and the
 * crowd are shared by restaurants of every kind, so ranking on them drifted
 * towards the grandest rooms (verified 2026-10-16). Cuisine and cooking style
 * only.
 */
const PLACE_TAG_TYPES = ["urn:tag:cuisine:qloo", "urn:tag:culinary_style:qloo"];
const BLAND = /^(place|restaurant|food|dining|casual|lively|locals|tourists|foodies|destination|special occasion)$/i;

type Json = Record<string, unknown>;

/**
 * Each restaurant's Qloo tags (its place entity is set in the data, verified
 * against Qloo's London search), read from insights in batches of 20.
 */
export const tagPlaces = internalAction({
  args: { brandId: v.id("emailBrands") },
  handler: async (ctx, { brandId }): Promise<string> => {
    const items: Doc<"emailItems">[] = await ctx.runQuery(internal.emailItems.listInternal, { brandId });
    const places = items.filter((i) => i.qloo?.type === "urn:entity:place");
    const updates: { id: Id<"emailItems">; qloo: { id: string; name: string; type: string; tags: string[] } }[] = [];
    for (let start = 0; start < places.length; start += 20) {
      const batch = places.slice(start, start + 20);
      const { body } = await cachedQlooGet(ctx, "/v2/insights", {
        "filter.type": "urn:entity:place",
        "filter.results.entities": batch.map((i) => i.qloo!.id).join(","),
        take: batch.length,
      });
      const byId = new Map(((JSON.parse(body) as { results?: { entities?: Json[] } }).results?.entities ?? []).map((e) => [String(e.entity_id), e]));
      for (const item of batch) {
        const e = byId.get(item.qloo!.id);
        if (!e) continue;
        const tags: string[] = [];
        for (const type of PLACE_TAG_TYPES) {
          for (const t of (e.tags as Json[] | undefined) ?? []) {
            const name = String(t.name ?? "").trim();
            if (t.type === type && name && !BLAND.test(name) && !tags.some((x) => x.toLowerCase() === name.toLowerCase())) tags.push(name);
          }
        }
        updates.push({ id: item._id, qloo: { id: item.qloo!.id, name: item.qloo!.name, type: item.qloo!.type, tags: tags.slice(0, 30) } });
      }
    }
    if (updates.length) await ctx.runMutation(internal.emailItems.setQloo, { updates });
    return `${updates.length} of ${places.length} restaurants tagged from Qloo`;
  },
});

/* Run ------------------------------------------------------------------------------- */

const rowsOf = (people: CoversContact[]) => people.map((p) => Object.fromEntries(COVERS_CONTACT_COLUMNS.map((k) => [k, String(p[k])])));

/**
 * Replaces Covers with a fresh master and starts reading its lists. Returns
 * once the regulars' reading is under way; `step` does the rest.
 */
export const run = internalAction({
  args: { site: v.optional(v.string()) },
  handler: async (ctx, { site = COVERS_SITE }): Promise<Record<string, unknown>> => {
    const t0 = Date.now();
    const base = site.replace(/\/$/, "");
    const old = await ctx.runQuery(internal.emailSeedCovers.existing, {});
    if (old) {
      // Account copies point at the old master's files and ids; they go with it.
      for (const id of old.copies) await purge(ctx, id);
      await dropAssets(ctx, old.master.kit as EmailKit | undefined);
      await dropCovers(ctx, old.master._id);
      await purge(ctx, old.master._id);
    }

    const kit = await storeAssets(ctx, base);
    const brandId = await ctx.runMutation(internal.emailSeedCovers.insertBrand, { site: base, kit });

    // The restaurants in the app's order, each already matched to its Qloo place; then their tags.
    const items = coversItems(base);
    await ctx.runMutation(internal.emailItems.append, { brandId, items });
    const tagged = await ctx.runAction(internal.emailSeedCovers.tagPlaces, { brandId });

    const columns = COVERS_CONTACT_COLUMNS.map(String);
    const regulars = await ctx.runMutation(api.emailLists.create, {
      brandId,
      name: "Regulars",
      filename: "regulars.csv",
      columns,
      mapping: COVERS_LIST_MAPPING,
      mode: "people",
      rows: rowsOf(COVERS_INDIVIDUALS),
      source: "demo",
    });
    const diners = await ctx.runMutation(api.emailLists.create, {
      brandId,
      name: "Members",
      filename: "members.csv",
      columns,
      mapping: COVERS_LIST_MAPPING,
      mode: "groups",
      rows: rowsOf(COVERS_DINERS),
      source: "demo",
    });

    // Reads the regulars' bookings now and schedules each person's profile.
    const read = await ctx.runAction(internal.emailLists.processInternal, { id: regulars.id });
    await ctx.scheduler.runAfter(15_000, internal.emailSeedCovers.step, { brandId, regularsId: regulars.id, dinersId: diners.id, stage: "regulars", attempt: 0, startedAt: t0 });
    return {
      brandId,
      restaurants: items.length,
      qloo: tagged,
      regularsList: regulars.id,
      dinersList: diners.id,
      regulars: `${read.resolved} of ${COVERS_INDIVIDUALS.length} people matched, ${read.unique} places from what they booked`,
      seconds: Math.round((Date.now() - t0) / 1000),
      next: "step follows the lists every 15 s; check with emailSeed:status '{\"slug\":\"covers\"}'",
    };
  },
});

/** Waits for the regulars to be read, then sorts the diners into two groups (k = 2: the two tastes they were written with), then finishes. */
export const step = internalAction({
  args: {
    brandId: v.id("emailBrands"),
    regularsId: v.id("emailLists"),
    dinersId: v.id("emailLists"),
    stage: v.union(v.literal("regulars"), v.literal("diners")),
    attempt: v.number(),
    startedAt: v.number(),
  },
  returns: v.null(),
  handler: async (ctx, args): Promise<null> => {
    const { brandId, regularsId, dinersId, stage, attempt, startedAt } = args;
    const again = () => ctx.scheduler.runAfter(15_000, internal.emailSeedCovers.step, { ...args, attempt: attempt + 1 });
    if (attempt > MAX_STEPS) {
      console.error(`emailSeedCovers: gave up waiting at stage ${stage}`);
      return null;
    }
    if (stage === "regulars") {
      const list: Doc<"emailLists"> | null = await ctx.runQuery(internal.emailLists.getInternal, { id: regularsId });
      if (!list) return null;
      if (list.status !== "ready" && list.status !== "failed") {
        await again();
        return null;
      }
      console.log(`emailSeedCovers: regulars ${list.status} after ${Math.round((Date.now() - startedAt) / 1000)} s`);
      await ctx.scheduler.runAfter(0, internal.emailLists.processInternal, { id: dinersId, k: 2 });
      await ctx.scheduler.runAfter(30_000, internal.emailSeedCovers.step, { ...args, stage: "diners", attempt: 0 });
      return null;
    }
    const list: Doc<"emailLists"> | null = await ctx.runQuery(internal.emailLists.getInternal, { id: dinersId });
    if (!list) return null;
    if (list.status !== "ready" && list.status !== "failed") {
      await again();
      return null;
    }
    console.log(`emailSeedCovers: diners ${list.status} after ${Math.round((Date.now() - startedAt) / 1000)} s`);
    if (list.status === "failed") return null;
    await ctx.runAction(internal.emailSeedCovers.finish, { brandId, startedAt });
    return null;
  },
});

/* Finish: groups and briefs ------------------------------------------------------------- */

type Audience = Doc<"emailAudiences">;
type Profile = AudienceProfile | undefined;
type GroupKey = keyof typeof COVERS_DINER_GROUPS;

/** "Haggerston, Dalston and Bethnal Green": where a group's people live. */
const homes = (members: ContactLite[]) => andList([...new Set(members.map((m) => m.neighborhood).filter((n): n is string => !!n))]);

/** Qloo's name for a restaurant → the app's ("BRAT Restaurant" → "Brat"). */
const OUR_NAME = new Map(COVERS_RESTAURANTS.map((r) => [r.qloo.id, r.name]));

/** "Brat ×2, Brawn ×2, Rochelle Canteen ×2": what the group booked most, by the app's names. */
function bookedMost(p: Profile, n: number): string {
  return (p?.entities ?? [])
    .filter((e) => e.type === "urn:entity:place")
    .slice(0, n)
    .map((e) => `${OUR_NAME.get(e.id) ?? e.name}${e.count && e.count > 1 ? ` ×${e.count}` : ""}`)
    .join(", ");
}

/** What Qloo adds beyond what they booked, of one kind ("Boiling Point, The Duke"). */
function qlooAdds(p: Profile, key: keyof AudienceProfile["culture"], n: number): string {
  const own = new Set((p?.entities ?? []).map((e) => e.id));
  return ((p?.culture?.[key] ?? []) as { id: string; name: string }[])
    .filter((e) => !own.has(e.id))
    .slice(0, n)
    .map((e) => OUR_NAME.get(e.id) ?? e.name)
    .join(", ");
}

/** Each group's read, in the app's words; the evidence is what its diners booked, where they live and Qloo's read of it. */
function groupBrief(key: GroupKey, p: Profile, members: ContactLite[]) {
  const booked = bookedMost(p, 5);
  const places = qlooAdds(p, "places", 3);
  const films = qlooAdds(p, "films", 3);
  const books = qlooAdds(p, "books", 2);
  const newcomers = members.filter((m) => !m.purchases?.length).map((m) => m.firstName ?? m.name);
  const where = homes(members);
  switch (key) {
    case "smallPlates":
      return {
        summary: "Diners who book east London's small-plates rooms: Brat, Brawn, Cafe Cecilia, Rochelle Canteen and Sessions Arts Club, with natural wine on the side. Most live a short walk from them.",
        speakTo: "Casual, curious and specific. Talk dishes, the wine list and the room; skip the superlatives.",
        leadWith: "A small-plates table near home in east London, with a dish worth booking for and a time that suits a weeknight.",
        hooks: [
          { text: "Brat and Brawn bookers follow the open fire and the wine list: lead with a grill and a short natural wine list.", evidence: cite([["They booked", booked], ["Qloo also suggests", places], ["On screen", films], ["Reading", books]]) },
          { text: "They book near home: Shoreditch, Hackney and Clerkenwell tables come first.", evidence: cite([["They live in", where]]) },
          {
            text: "New members here haven't booked yet: invite them to a first table, never thank them for one.",
            evidence: cite([["No bookings yet", andList(newcomers)], ["Placed by", newcomers.length ? "age, gender and how close they live to the group's restaurants" : ""]]),
          },
        ],
      };
    case "grandRooms":
      return {
        summary: "Diners who book London's grand rooms for big nights: The Wolseley, Scott's, Rules, Clos Maggiore, Bob Bob Ricard and sketch.",
        speakTo: "Assured and warm, a touch more formal: talk about the occasion, the room and the service, never the price.",
        leadWith: "A big-night table (a birthday, an anniversary, a theatre supper) in a classic West End room, with the dish it's known for.",
        hooks: [
          { text: "Wolseley and Scott's regulars want the classics done properly: Dover sole, a soufflé, a good table.", evidence: cite([["They booked", booked], ["Qloo also suggests", places]]) },
          { text: "They book for occasions: Clos Maggiore's conservatory and Bob Bob Ricard's champagne buttons.", evidence: cite([["They booked", booked], ["On screen, Qloo pairs them with", films], ["Reading", books]]) },
          { text: "Piccadilly and Covent Garden are close to home: pre-theatre and Sunday tables suit them.", evidence: cite([["They live in", where], ["No bookings yet", andList(newcomers)]]) },
        ],
      };
  }
}

/** Names each taste group after the diners most of its people were written as, writes its brief, then copies the photos into storage. */
export const finish = internalAction({
  args: { brandId: v.id("emailBrands"), startedAt: v.optional(v.number()) },
  handler: async (ctx, { brandId, startedAt }): Promise<Record<string, unknown>> => {
    const audiences: Audience[] = await ctx.runQuery(internal.emailAudiences.listInternal, { brandId });
    const groups = audiences.filter((a) => a.kind === "group");
    const membersOf = new Map<string, ContactLite[]>();
    for (const a of groups) membersOf.set(a._id, await ctx.runQuery(internal.emailContacts.byAudienceInternal, { audienceId: a._id }));
    const pairs: { audience: Audience; key: GroupKey; n: number }[] = [];
    for (const a of groups) {
      const emails = new Set(membersOf.get(a._id)!.map((m) => m.email));
      for (const key of Object.keys(COVERS_DINER_GROUPS) as GroupKey[]) {
        pairs.push({ audience: a, key, n: COVERS_DINER_GROUPS[key].emails.filter((e) => emails.has(e)).length });
      }
    }
    pairs.sort((x, y) => y.n - x.n);
    const named = new Map<string, GroupKey>();
    const used = new Set<GroupKey>();
    for (const p of pairs) {
      if (named.has(p.audience._id) || used.has(p.key) || p.n === 0) continue;
      named.set(p.audience._id, p.key);
      used.add(p.key);
    }
    const groupReport: string[] = [];
    for (const a of groups) {
      const key = named.get(a._id);
      const members = membersOf.get(a._id)!;
      const intended = key ? COVERS_DINER_GROUPS[key].emails.filter((e) => members.some((m) => m.email === e)).length : 0;
      if (key) await ctx.runMutation(internal.emailAudiences.setBrief, { id: a._id, name: COVERS_DINER_GROUPS[key].name, brief: groupBrief(key, a.profile as Profile, members) });
      const placed = members.filter((m) => m.placement).map((m) => `${m.firstName ?? m.name} (${m.placement!.note})`);
      groupReport.push(
        `${key ? COVERS_DINER_GROUPS[key].name : a.name}: ${members.length} people (${intended} as written), ${a.status}, top ${a.topEntities.slice(0, 3).join(", ")}${placed.length ? `; placed: ${placed.join("; ")}` : ""}`,
      );
    }
    const photos = await ctx.runAction(internal.emailSeed.mirrorCovers, { brandId });
    const result = { groups: groupReport, photos, ...(startedAt ? { seconds: Math.round((Date.now() - startedAt) / 1000) } : {}) };
    console.log("emailSeedCovers: finished", JSON.stringify(result));
    return result;
  },
});

/* Assets ------------------------------------------------------------------------------------ */

// apps/stores/public/covers/logo.png, logo-light.png (172 × 40 at 2x) and
// mark.png (256 × 256), base64, so the seed can store them without reaching the
// site. The round plate mark is the user's (dining_logo.png, cropped to the circle).
const LOGO_PNG = "";
const LOGO_LIGHT_PNG = "";
const MARK_PNG = "";
